$f=$GLOBALS['cli_fixture']; $expected=array();
foreach($f['routes'] as $key=>$value) { if(str_starts_with($key,'https://cli-old.example.test/')) { $key='https://cli-new.example.test'.substr($key,strlen('https://cli-old.example.test')); } $expected[$key]=$value; }
